INSERT INTO `assessment_results` (`id`, `submission_id`, `total_score`, `max_score`, `percentage`, `overall_interpretation`, `pre_post_diff`, `created_at`, `updated_at`, `rqi_score`, `category_name`, `who5_raw_score`, `who5_percentage`, `who5_screening_note`, `reflection_text`, `scoring_version`, `snapshot_data`, `dimension_scores`) VALUES ('99', '99', '43', '75', '57.33', 'On track! Fondasi God Spot dan ketaatan ibadah udah lumayan konsisten. Akhlak sosial mulai kerasa green flag-nya, tinggal ngelatih ketenangan pas lagi banyak tekanan.', NULL, '2026-09-25 04:17:44', '2026-09-25 04:17:44', '43', 'Level 3: Developing Soul (Jiwa Berproses Stabil)', '11', '44', 'Kondisi mental kamu lumayan stabil, tapi kadang masih gampang goyah kalau lagi banyak tekanan. Masih bisa enjoy hari-hari walau sesekali ngerasa capek fisik atau pikiran.', NULL, '1.0', '{\"instrument_code\":\"RQI-15\",\"version\":\"1.0\",\"total_score\":43,\"category\":{\"level\":3,\"name\":\"Level 3: Developing Soul (Jiwa Berproses Stabil)\",\"short_name\":\"Developing Soul\",\"level_code\":\"DEVELOPING_SOUL\",\"score_range\":\"41 \\u2013 53\",\"description\":\"On track! Fondasi God Spot dan ketaatan ibadah udah lumayan konsisten. Akhlak sosial mulai kerasa green flag-nya, tinggal ngelatih ketenangan pas lagi banyak tekanan.\"},\"who5\":{\"raw_score\":11,\"max_raw\":25,\"percentage\":44,\"screening_note\":\"Kondisi mental kamu lumayan stabil, tapi kadang masih gampang goyah kalau lagi banyak tekanan. Masih bisa enjoy hari-hari walau sesekali ngerasa capek fisik atau pikiran.\",\"level\":3,\"name\":\"Level 3: Moderate Well-Being (Cukup Stabil)\",\"short_name\":\"Moderate Well-Being\",\"percentage_range\":\"44% \\u2013 56%\",\"description\":\"Kondisi mental kamu lumayan stabil, tapi kadang masih gampang goyah kalau lagi banyak tekanan. Masih bisa enjoy hari-hari walau sesekali ngerasa capek fisik atau pikiran.\",\"badge_color\":\"bg-amber-500 text-slate-950 border-amber-300\",\"needs_attention\":false},\"dimension_scores\":{\"1\":{\"dimension_id\":1,\"score\":6,\"max_score\":15},\"2\":{\"dimension_id\":2,\"score\":8,\"max_score\":15},\"3\":{\"dimension_id\":3,\"score\":11,\"max_score\":15},\"4\":{\"dimension_id\":4,\"score\":10,\"max_score\":15},\"5\":{\"dimension_id\":5,\"score\":8,\"max_score\":15}}}', NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `assessment_results` (`id`, `submission_id`, `total_score`, `max_score`, `percentage`, `overall_interpretation`, `pre_post_diff`, `created_at`, `updated_at`, `rqi_score`, `category_name`, `who5_raw_score`, `who5_percentage`, `who5_screening_note`, `reflection_text`, `scoring_version`, `snapshot_data`, `dimension_scores`) VALUES ('100', '100', '60', '75', '80', 'Udah zen banget. Self-awareness tinggi, anti-prokrastinasi, dan ibadah berasa jadi mental detox yang bikin adem. God Light mulai aktif ngebimbing pilihan hidup.', NULL, '2026-09-25 04:17:47', '2026-09-25 04:17:47', '60', 'Level 4: Mindful Youth (Jiwa Tenang & Terjaga)', '9', '36', 'Lagi sering overthinking dan gampang cemas. Baterai sosial dan fisik kamu sering habis sebelum waktunya. Kurang-kurangin memforsir diri dan perbanyak me time yang positif.', NULL, '1.0', '{\"instrument_code\":\"RQI-15\",\"version\":\"1.0\",\"total_score\":60,\"category\":{\"level\":4,\"name\":\"Level 4: Mindful Youth (Jiwa Tenang & Terjaga)\",\"short_name\":\"Mindful Youth\",\"level_code\":\"MINDFUL_YOUTH\",\"score_range\":\"54 \\u2013 64\",\"description\":\"Udah zen banget. Self-awareness tinggi, anti-prokrastinasi, dan ibadah berasa jadi mental detox yang bikin adem. God Light mulai aktif ngebimbing pilihan hidup.\"},\"who5\":{\"raw_score\":9,\"max_raw\":25,\"percentage\":36,\"screening_note\":\"Lagi sering overthinking dan gampang cemas. Baterai sosial dan fisik kamu sering habis sebelum waktunya. Kurang-kurangin memforsir diri dan perbanyak me time yang positif.\",\"level\":2,\"name\":\"Level 2: Low Energy (Sering Cemas)\",\"short_name\":\"Low Energy\",\"percentage_range\":\"24% \\u2013 40%\",\"description\":\"Lagi sering overthinking dan gampang cemas. Baterai sosial dan fisik kamu sering habis sebelum waktunya. Kurang-kurangin memforsir diri dan perbanyak me time yang positif.\",\"badge_color\":\"bg-orange-600 text-white border-orange-400\",\"needs_attention\":true},\"dimension_scores\":{\"1\":{\"dimension_id\":1,\"score\":9,\"max_score\":15},\"2\":{\"dimension_id\":2,\"score\":13,\"max_score\":15},\"3\":{\"dimension_id\":3,\"score\":13,\"max_score\":15},\"4\":{\"dimension_id\":4,\"score\":13,\"max_score\":15},\"5\":{\"dimension_id\":5,\"score\":12,\"max_score\":15}}}', NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `assessment_results` (`id`, `submission_id`, `total_score`, `max_score`, `percentage`, `overall_interpretation`, `pre_post_diff`, `created_at`, `updated_at`, `rqi_score`, `category_name`, `who5_raw_score`, `who5_percentage`, `who5_screening_note`, `reflection_text`, `scoring_version`, `snapshot_data`, `dimension_scores`) VALUES ('101', '101', '37', '75', '49.33', 'Mulai sadar kalau hidup butuh arah yang bener. Sadar diri dan niat ibadah mulai tumbuh, tapi rem batin masih sering jebol kalau kena godaan atau stres harian.', NULL, '2026-09-25 04:17:50', '2026-09-25 04:17:50', '37', 'Level 2: Awakening Pilgrim (Jiwa Mulai Tergugah)', '4', '16', 'Mental kamu lagi di titik terendah alias burnout parah. Energi habis, susah tidur nyenyak, dan hari-hari terasa berat banget. Saatnya prioritize rest dan cari support system!', NULL, '1.0', '{\"instrument_code\":\"RQI-15\",\"version\":\"1.0\",\"total_score\":37,\"category\":{\"level\":2,\"name\":\"Level 2: Awakening Pilgrim (Jiwa Mulai Tergugah)\",\"short_name\":\"Awakening Pilgrim\",\"level_code\":\"AWAKENING_PILGRIM\",\"score_range\":\"27 \\u2013 40\",\"description\":\"Mulai sadar kalau hidup butuh arah yang bener. Sadar diri dan niat ibadah mulai tumbuh, tapi rem batin masih sering jebol kalau kena godaan atau stres harian.\"},\"who5\":{\"raw_score\":4,\"max_raw\":25,\"percentage\":16,\"screening_note\":\"Mental kamu lagi di titik terendah alias burnout parah. Energi habis, susah tidur nyenyak, dan hari-hari terasa berat banget. Saatnya prioritize rest dan cari support system!\",\"level\":1,\"name\":\"Level 1: Mental Exhausted (Burnout Parah)\",\"short_name\":\"Mental Exhausted\",\"percentage_range\":\"0% \\u2013 20%\",\"description\":\"Mental kamu lagi di titik terendah alias burnout parah. Energi habis, susah tidur nyenyak, dan hari-hari terasa berat banget. Saatnya prioritize rest dan cari support system!\",\"badge_color\":\"bg-rose-600 text-white border-rose-400\",\"needs_attention\":true},\"dimension_scores\":{\"1\":{\"dimension_id\":1,\"score\":7,\"max_score\":15},\"2\":{\"dimension_id\":2,\"score\":7,\"max_score\":15},\"3\":{\"dimension_id\":3,\"score\":8,\"max_score\":15},\"4\":{\"dimension_id\":4,\"score\":8,\"max_score\":15},\"5\":{\"dimension_id\":5,\"score\":7,\"max_score\":15}}}', NULL) ON DUPLICATE KEY UPDATE id=id;
